use crate::{self as models, de_optlink, de_optstring, de_string};
use serde::{Deserialize, Serialize};
use utoipa::ToSchema;

/// plenary session, committee session or committee hearing.
/// A session is a hearing if experts are invited.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToSchema)]
#[serde(remote = "Self")]
pub struct Sitzung {
    /// optional, here for future references. Is generated by the server.
    /// If you set it use UUID version 5 with your collector id as namespace
    #[serde(skip_serializing_if = "Option::is_none")]
    pub api_id: Option<uuid::Uuid>,

    /// list of scraper uuids / key database ids that have touched this object
    #[serde(skip_serializing_if = "Vec::is_empty", default = "Vec::new")]
    pub touched_by: Vec<models::TouchedByInner>,

    /// Title if applicable
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(deserialize_with = "de_optstring", default)]
    pub titel: Option<String>,

    pub termin: chrono::DateTime<chrono::Utc>,

    pub gremium: models::Gremium,

    pub nummer: u16,

    pub public: bool,

    #[schema(format = "uri")]
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(deserialize_with = "de_optlink", default)]
    pub link: Option<String>,

    pub tops: Vec<models::Top>,

    /// Announcements, agendas and changed/amended agendas
    #[serde(skip_serializing_if = "Vec::is_empty", default = "Vec::new")]
    pub dokumente: Vec<models::DokumentOrApiId>,

    /// List of invited experts. if this is not null or empty, a session is a hearing.
    #[serde(skip_serializing_if = "Vec::is_empty", default = "Vec::new")]
    pub experten: Vec<models::Autor>,
}
impl std::default::Default for Sitzung {
    fn default() -> Self {
        Self {
            touched_by: vec![],
            titel: None,
            link: None,
            api_id: None,
            dokumente: vec![],
            experten: vec![],
            tops: vec![],
            termin: chrono::Utc::now(),
            nummer: 0,
            public: true,
            gremium: models::Gremium {
                link: None,
                name: "default".to_owned(),
                parlament: models::Parlament::Bt,
                wahlperiode: 1,
            },
        }
    }
}

impl std::fmt::Display for Sitzung {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let params: Vec<Option<String>> = vec![
            self.titel.as_ref().map(|titel| ["titel", titel].join(",")),
            Some("nummer".to_string()),
            Some(self.nummer.to_string()),
            Some("public".to_string()),
            Some(self.public.to_string()),
            self.link.as_ref().map(|link| ["link", link].join(",")),
        ];

        write!(
            f,
            "{}",
            params.into_iter().flatten().collect::<Vec<_>>().join(",")
        )
    }
}

/// An item on the agenda
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToSchema)]
#[serde(remote = "Self")]
pub struct Top {
    /// number of this item on the agenda
    pub nummer: u16,

    #[serde(deserialize_with = "de_string")]
    pub titel: String,

    /// api ids of associated Vorgang objects.
    /// Is ignored at upload time, but passed at download time.
    /// The matching happens via the documents supplied below
    #[serde(skip_serializing_if = "Vec::is_empty", default = "Vec::new")]
    pub vorgang_id: Vec<uuid::Uuid>,

    /// documents handled in this agenda item
    #[serde(skip_serializing_if = "Vec::is_empty", default = "Vec::new")]
    pub dokumente: Vec<models::DokumentOrApiId>,
}

impl std::fmt::Display for Top {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let params: Vec<Option<String>> = vec![
            Some("nummer".to_string()),
            Some(self.nummer.to_string()),
            Some("titel".to_string()),
            Some(self.titel.clone()),
        ];

        write!(
            f,
            "{}",
            params.into_iter().flatten().collect::<Vec<_>>().join(",")
        )
    }
}

#[cfg(test)]
#[allow(
    clippy::expect_used,
    reason = "in test cases, love and war all things are allowed"
)]
mod test_sitzung {
    #[test]
    fn deserialize_sitzung_dokumente() {
        let s: Result<super::Sitzung, _> = serde_json::from_str(include_str!(
            "../../pazufa-backend-lib/tests/serialization/sitzung.json"
        ));
        assert!(
            s.is_err(),
            "Expected to fail due to documents supplied by api id"
        );
    }
    #[test]
    fn deserialize_fail_sitzung_tops_dokumente() {
        let s: Result<super::Sitzung, _> = serde_json::from_str(include_str!(
            "./../../pazufa-backend-lib/tests/serialization/sitzung-minimal.json"
        ));
        assert!(
            s.is_err(),
            "Expected to fail due to documents supplied by api id"
        );
    }
}
